UPDATE source_file SET file_key=#{fileKey}, generation=#{generation}, byte_offset=#{byteOffset},
  anchor_hash=#{anchorHash}, observed_size=#{observedSize}, modified_at=#{modifiedAt}, scanned_at=#{scannedAt}
WHERE id=#{id}

mapper.select:
SELECT * FROM raw_jsonl_record WHERE id > #{afterId}
AND source_id = #{sourceId}
AND parse_status = #{parseStatus}
ORDER BY id LIMIT #{limit}

SELECT * FROM normalization_job
WHERE status = 'PENDING' AND available_at <= #{now}
ORDER BY id LIMIT 1

mapper.update:
UPDATE hook_session SET transcript_path=#{transcriptPath}, started_at=#{startedAt}, ended_at=#{endedAt},
  state=#{state}, last_observed_at=#{lastObservedAt}, version=version+1
WHERE session_id_sha256=UNHEX(SHA2(#{sessionId}, 256)) AND session_id=#{sessionId}

UPDATE hook_tool_call SET tool_name=#{toolName}, pre_observed_at=#{preObservedAt}, post_observed_at=#{postObservedAt},
  state=#{state}, estimated_duration_ms=#{estimatedDurationMs}, duration_valid=#{durationValid}, version=version+1
WHERE session_id_sha256=UNHEX(SHA2(#{sessionId}, 256)) AND session_id=#{sessionId}
  AND turn_id_sha256=UNHEX(SHA2(#{turnId}, 256)) AND turn_id=#{turnId}
  AND tool_use_id_sha256=UNHEX(SHA2(#{toolUseId}, 256)) AND tool_use_id=#{toolUseId}

mapper.select:
SELECT t.session_id, t.turn_id, t.started_at, t.ended_at, t.state, s.transcript_path, COALESCE((SELECT (JSON_UNQUOTE(JSON_EXTRACT(h.raw_json, '$.prompt')) COLLATE utf8mb4_0900_bin) FROM raw_hook_event h WHERE (JSON_UNQUOTE(JSON_EXTRACT(h.raw_json, '$.turn_id')) COLLATE utf8mb4_0900_bin)=t.turn_id AND (JSON_UNQUOTE(JSON_EXTRACT(h.raw_json, '$.hook_event_name')) COLLATE utf8mb4_0900_bin)='UserPromptSubmit' ORDER BY h.id LIMIT 1),'等待用户问题内容补齐') title, (SELECT (JSON_UNQUOTE(JSON_EXTRACT(h.raw_json, '$.model')) COLLATE utf8mb4_0900_bin) FROM raw_hook_event h WHERE (JSON_UNQUOTE(JSON_EXTRACT(h.raw_json, '$.turn_id')) COLLATE utf8mb4_0900_bin)=t.turn_id ORDER BY h.id LIMIT 1) model, (SELECT (JSON_UNQUOTE(JSON_EXTRACT(h.raw_json, '$.cwd')) COLLATE utf8mb4_0900_bin) FROM raw_hook_event h WHERE (JSON_UNQUOTE(JSON_EXTRACT(h.raw_json, '$.turn_id')) COLLATE utf8mb4_0900_bin)=t.turn_id ORDER BY h.id LIMIT 1) cwd, b.path_status transcript_path_status,b.session_check_status, (SELECT COUNT(*) FROM hook_tool_call x WHERE x.turn_id=t.turn_id) tool_count, (SELECT SUM(estimated_duration_ms) FROM hook_tool_call x WHERE x.turn_id=t.turn_id AND duration_valid=1) tool_ms, (SELECT COUNT(DISTINCT a.hook_node_id) FROM performance_alignment a JOIN hook_tool_call x ON x.tool_use_id=a.hook_node_id WHERE x.turn_id=t.turn_id AND a.level='EXACT') otel_tool_count, CASE WHEN t.started_at IS NOT NULL AND t.ended_at >= t.started_at THEN t.ended_at-t.started_at END duration_ms FROM hook_turn t JOIN hook_session s ON s.session_id=t.session_id LEFT JOIN transcript_binding b ON b.session_id=t.session_id
WHERE lower(t.session_id) LIKE CONCAT('%', lower(#{query}), '%') OR lower(t.turn_id) LIKE CONCAT('%', lower(#{query}), '%')
ORDER BY COALESCE(t.started_at, 0) DESC, t.turn_id LIMIT #{limit} OFFSET #{offset}
